{"domains/classification/model.py": "import json
import math
from pathlib import Path


def _check_finite(obj):
    if isinstance(obj, float):
        if math.isnan(obj) or math.isinf(obj):
            raise ValueError("non-finite number")
    elif isinstance(obj, dict):
        for v in obj.values():
            _check_finite(v)
    elif isinstance(obj, list):
        for v in obj:
            _check_finite(v)


def load_payload(path: Path):
    text = path.read_text(encoding="utf-8")
    try:
        data = json.loads(text)
    except json.JSONDecodeError as e:
        raise ValueError("invalid JSON") from e
    if not isinstance(data, (dict, list)):
        raise ValueError("top-level must be object or array")
    _check_finite(data)
    return data
", "domains/classification/transform.py": "import re


def _business_input(payload):
    if isinstance(payload, dict) and set(payload) == {"name", "result"}:
        return payload["result"]
    return payload


def transform(payloads, contract):
    if len(payloads) != len(contract["inputs"]):
        raise ValueError("payload count mismatch")
    documents = _business_input(payloads[0])
    if not isinstance(documents, dict) or "documents" not in documents:
        raise ValueError("missing documents")
    docs = documents["documents"]
    if not isinstance(docs, list):
        raise ValueError("documents must be a list")

    classes = {}
    seen_ids = set()
    for doc in docs:
        if not isinstance(doc, dict):
            raise ValueError("document must be object")
        if "id" not in doc or "text" not in doc:
            raise ValueError("document missing id/text")
        doc_id = doc["id"]
        if not isinstance(doc_id, str) or not doc_id.strip():
            raise ValueError("invalid id")
        if doc_id in seen_ids:
            raise ValueError("duplicate id")
        seen_ids.add(doc_id)
        text = doc["text"]
        if not isinstance(text, str):
            raise ValueError("text must be string")
        words = set(re.findall(r"[A-Za-z]+", text.lower()))
        if "invoice" in words:
            kind = "invoice"
        elif "receipt" in words:
            kind = "receipt"
        else:
            kind = "other"
        classes[doc_id] = kind

    return {"name": contract["name"], "result": {"classes": classes}}
", "domains/classification/render.py": "import json
import sys
from pathlib import Path

from model import load_payload
from transform import transform


def build_component(root: Path, contract_path: Path):
    contract = load_payload(contract_path)
    payloads = [load_payload(root / p) for p in contract["inputs"]]
    return transform(payloads, contract)


def main():
    root = Path.cwd()
    contract_path = Path(__file__).with_name("contract.json")
    contract = load_payload(contract_path)
    result = build_component(root, contract_path)
    out = root / contract["output"]
    out.parent.mkdir(parents=True, exist_ok=True)
    out.write_text(
        json.dumps(result, ensure_ascii=False, sort_keys=True, indent=2, allow_nan=False) + "\n",
        encoding="utf-8",
    )


if __name__ == "__main__":
    main()
"}

