class TestClassification(unittest.TestCase):
    def test_transform_shape_and_rules(self):
        contract = {"name": "classification", "inputs": ["inputs/case.json"]}
        payload = {
            "documents": [
                {"id": "a", "filename": "x.txt", "text": "Invoice here"},
                {"id": "b", "filename": "y.txt", "text": "a Receipt note"},
                {"id": "c", "filename": "z.txt", "text": "nothing"},
            ]
        }
        result = transform([payload], contract)
        self.assertEqual(set(result), {"name", "result"})
        self.assertEqual(result["name"], "classification")
        self.assertEqual(
            result["result"]["classes"],
            {"a": "invoice", "b": "receipt", "c": "other"},
        )

    def test_case_insensitive_word(self):
        contract = {"name": "classification", "inputs": ["x"]}
        payload = {"documents": [{"id": "a", "text": "INVOICE"}]}
        self.assertEqual(transform([payload], contract)["result"]["classes"], {"a": "invoice"})

    def test_duplicate_id_raises(self):
        contract = {"name": "classification", "inputs": ["x"]}
        payload = {"documents": [{"id": "a", "text": "Invoice"}, {"id": "a", "text": "Receipt"}]}
        with self.assertRaises(ValueError):
            transform([payload], contract)

