        import tempfile
        with tempfile.NamedTemporaryFile("w", suffix=".json", delete=False) as f:
            f.write('{"a": NaN}')
            name = f.name
        try:
            with self.assertRaises(ValueError):
                load_payload(Path(name))
        finally:
            Path(name).unlink()


