import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent


def _contracts():
    result = []
    for cp in sorted(ROOT.rglob('contract.json')):
        rel = cp.relative_to(ROOT)
        if 'outputs' in rel.parts:
            continue
        result.append(cp)
    return result


def main():
    contracts = _contracts()
    if not contracts:
        raise ValueError('no contracts')

    produced = {}
    for cp in contracts:
        c = json.loads(cp.read_text(encoding='utf-8'))
        produced[c['name']] = cp

    remaining = list(contracts)
    done = set()
    while remaining:
        progressed = False
        for cp in list(remaining):
            c = json.loads(cp.read_text(encoding='utf-8'))
            deps = []
            for inp in c['inputs']:
                for name, producer in produced.items():
                    if name == c['name']:
                        continue
                    pc = json.loads(producer.read_text(encoding='utf-8'))
                    if pc['output'] == inp:
                        deps.append(name)
            if all(d in done for d in deps):
                subprocess.run(
                    [sys.executable, str(cp.with_name('render.py')), str(cp)],
                    cwd=ROOT, check=True, timeout=180,
                )
                done.add(c['name'])
                remaining.remove(cp)
                progressed = True
        if not progressed:
            raise ValueError('dependency cycle or missing dependency')

    subprocess.run(
        [sys.executable, str(ROOT / 'integrate.py')],
        cwd=ROOT, check=True, timeout=180,
    )


if __name__ == '__main__':
    main()
"}

{"final_report.py": "import hashlib
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent


def _attention(components):
    names = []
    for name, result in components.items():
        if not isinstance(result, dict):
            continue
        if result.get("blocked") is True:
            names.append(name)
            continue
        for key in ("complete", "checkout", "committed", "ok"):
            if result.get(key) is False:
                names.append(name)
                break
        else:
            for key in ("unavailable", "missing", "conflicts", "unreachable"):
                v = result.get(key)
                if isinstance(v, (list, dict, str, tuple)) and len(v) > 0:
                    names.append(name)
                    break
    return sorted(set(names))


def main():
    core_path = ROOT / "outputs" / "core_manifest.json"
    core = json.loads(core_path.read_text(encoding="utf-8"))
    components = core["components"]

    serialized = json.dumps(
        core,
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
        allow_nan=False,
    ).encode("utf-8")
    sha256 = hashlib.sha256(serialized).hexdigest()

    report = {
        "title": "文本票据分类、金额提取与归档汇总",
        "component_count": len(components),
        "sha256": sha256,
        "attention": _attention(components),
    }

    out = ROOT / "outputs" / "final_report.json"
    out.parent.mkdir(parents=True, exist_ok=True)
    out.write_text(
        json.dumps(report, ensure_ascii=False, sort_keys=True, indent=2, allow_nan=False) + "\n",
        encoding="utf-8",
    )


if __name__ == "__main__":
    main()
"}

